$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot = Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/access_control_phase4_$stamp"

function Read-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)

    $path = Join-Path $root $RelativePath
    if (-not (Test-Path $path)) {
        throw "Required file not found: $RelativePath"
    }

    return [IO.File]::ReadAllText($path).Replace("`r`n", "`n")
}

function Write-ProjectFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Content
    )

    $path = Join-Path $root $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $path -Parent) -Force | Out-Null
    [IO.File]::WriteAllText($path, $Content, $utf8)
    Write-Host "Created/updated: $RelativePath" -ForegroundColor Green
}

function Backup-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)

    $source = Join-Path $root $RelativePath
    if (-not (Test-Path $source)) { return }

    $destination = Join-Path $backupRoot $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $destination -Parent) -Force | Out-Null
    Copy-Item $source $destination -Force
}

function Add-Import {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$ImportLine
    )

    if ($Content.Contains($ImportLine)) { return $Content }

    $matches = [regex]::Matches(
        $Content,
        "(?m)^import\s+['""].+?['""];\s*$"
    )

    if ($matches.Count -eq 0) {
        throw "Import block not found: $ImportLine"
    }

    $last = $matches[$matches.Count - 1]

    return $Content.Insert(
        $last.Index + $last.Length,
        "`n$ImportLine"
    )
}

$payloads = @{
    'firestore.rules' = ''
    'firestore.indexes.json' = 'ewogICJpbmRleGVzIjogW10sCiAgImZpZWxkT3ZlcnJpZGVzIjogW10KfQo='
    'lib/features/access_control/data/services/access_control_migration_service.dart' = ''
    'lib/features/access_control/presentation/pages/access_control_production_readiness_page.dart' = ''
    'docs/roles_permissions_phase4_production_deployment.md' = ''
}
$firebaseJson = 'firebase.json'
$rolesPage = 'lib/features/access_control/presentation/pages/roles_permissions_page.dart'
$assignmentRepository = 'lib/features/access_control/data/repositories/user_role_assignment_repository_impl.dart'
$assignmentForm = 'lib/features/access_control/presentation/pages/user_role_assignment_form_page.dart'

foreach ($relativePath in (@(
    $firebaseJson,
    $rolesPage,
    $assignmentRepository,
    $assignmentForm
) + $payloads.Keys)) {
    Backup-ProjectFile -RelativePath $relativePath
}

foreach ($item in $payloads.GetEnumerator()) {
    $text = [Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($item.Value)
    )

    Write-ProjectFile `
        -RelativePath $item.Key `
        -Content $text
}

# Canonicalize all future assignments to user_roles/{FirebaseAuthUID}.
$content = Read-ProjectFile -RelativePath $assignmentRepository

$oldSave = @'
    await _service
        .collection(FirestorePaths.userRoleAssignments)
        .doc(assignment.id)
        .set(
          UserRoleAssignmentModel.fromEntity(assignment).toMap(),
        );
'@

$newSave = @'
    await _service
        .collection(FirestorePaths.userRoleAssignments)
        .doc(assignment.userId.trim())
        .set(
          UserRoleAssignmentModel.fromEntity(assignment).toMap(),
        );

    if (assignment.id != assignment.userId.trim()) {
      await _service
          .collection(FirestorePaths.userRoleAssignments)
          .doc(assignment.id)
          .delete();
    }
'@

if ($content.Contains($oldSave)) {
    $content = $content.Replace($oldSave, $newSave)
} elseif (-not $content.Contains('.doc(assignment.userId.trim())')) {
    throw 'User role save anchor not found.'
}

Write-ProjectFile `
    -RelativePath $assignmentRepository `
    -Content $content

# New assignments use the UID as their entity/document ID.
$content = Read-ProjectFile -RelativePath $assignmentForm

$oldId = @'
        id: old?.id ??
            sl<UserRoleAssignmentRepository>().generateId(),
'@

$newId = @'
        id: old?.id ?? _userId.text.trim(),
'@

if ($content.Contains($oldId)) {
    $content = $content.Replace($oldId, $newId)
} elseif (-not $content.Contains(
    'id: old?.id ?? _userId.text.trim()'
)) {
    throw 'User assignment ID anchor not found.'
}

Write-ProjectFile `
    -RelativePath $assignmentForm `
    -Content $content

# Add Production Readiness button.
$content = Read-ProjectFile -RelativePath $rolesPage

$content = Add-Import `
    -Content $content `
    -ImportLine "import 'access_control_production_readiness_page.dart';"

if (-not $content.Contains(
    'const AccessControlProductionReadinessPage()'
)) {
    $actionsAnchor = @'
        actions: [
'@

    $index = $content.IndexOf($actionsAnchor)

    if ($index -lt 0) {
        throw 'Roles page AppBar actions anchor not found.'
    }

    $insertIndex = $index + $actionsAnchor.Length

    $button = @'
          TextButton.icon(
            onPressed: () {
              Navigator.of(context).push<void>(
                MaterialPageRoute<void>(
                  builder: (_) =>
                      const AccessControlProductionReadinessPage(),
                ),
              );
            },
            icon: const Icon(Icons.security_outlined),
            label: const Text('Production Readiness'),
          ),
'@

    $content = $content.Insert($insertIndex, $button)
}

Write-ProjectFile -RelativePath $rolesPage -Content $content

# Preserve FlutterFire configuration and add Firestore deployment files.
$firebasePath = Join-Path $root $firebaseJson
$firebaseConfig = Get-Content $firebasePath -Raw | ConvertFrom-Json

if ($null -eq $firebaseConfig.firestore) {
    $firebaseConfig | Add-Member `
        -NotePropertyName 'firestore' `
        -NotePropertyValue ([pscustomobject]@{
            rules = 'firestore.rules'
            indexes = 'firestore.indexes.json'
        })
} else {
    $firebaseConfig.firestore.rules = 'firestore.rules'
    $firebaseConfig.firestore.indexes = 'firestore.indexes.json'
}

$firebaseContent = $firebaseConfig |
    ConvertTo-Json -Depth 20

Write-ProjectFile `
    -RelativePath $firebaseJson `
    -Content ($firebaseContent + "`n")

$formatFiles = @(
    $rolesPage,
    $assignmentRepository,
    $assignmentForm,
    'lib/features/access_control/data/services/access_control_migration_service.dart',
    'lib/features/access_control/presentation/pages/access_control_production_readiness_page.dart'
)

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan

& dart format $formatFiles

if ($LASTEXITCODE -ne 0) {
    throw 'dart format failed.'
}

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan

& flutter analyze

if ($LASTEXITCODE -ne 0) {
    throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Roles and Permissions Phase 4 staging completed successfully.' -ForegroundColor Green
Write-Host 'IMPORTANT: Firestore rules were staged but NOT deployed.' -ForegroundColor Yellow
Write-Host 'Run migration and production readiness validation inside the app before deployment.' -ForegroundColor Yellow
Write-Host "Deployment guide: docs/roles_permissions_phase4_production_deployment.md" -ForegroundColor Cyan
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
